                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc));q.append((nr,nc))
    # Mark all enclosed empty regions, leaving each region's central cell empty.
    remaining={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in outside}
    interior=set()
    while remaining:
        p=remaining.pop(); comp={p}; stack=[p]
        while stack:
            r,c=stack.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                t=(r+dr,c+dc)
                if t in remaining:
                    remaining.remove(t);comp.add(t);stack.append(t)
        r0=min(r for r,c in comp);r1=max(r for r,c in comp)
        c0=min(c for r,c in comp);c1=max(c for r,c in comp)
        center=((r0+r1+1)//2,(c0+c1)//2)
        for cell in comp:
            if cell!=center: interior.add(cell)
    # Halo around any 1; interior fill has precedence over the halo.
    halo=set()
    for r in range(h):
