    import collections
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    # Flood-fill zeroes connected to the grid boundary (4-connectivity).
    exterior=set();q=collections.deque()
    for r in range(h):
      for c in range(w):
        if (r in (0,h-1) or c in (0,w-1)) and grid[r][c]==0:exterior.add((r,c));q.append((r,c))
    while q:
      r,c=q.popleft()
      for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in exterior:exterior.add((nr,nc));q.append((nr,nc))
    enclosed={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in exterior}
    # Draw an 8-neighbour halo around the outlines on exterior/background zeros.
    for r in range(h):
      for c in range(w):
        if grid[r][c]==1:
          for dr in (-1,0,1):
            for dc in (-1,0,1):
              nr,nc=r+dr,c+dc
              if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in enclosed:out[nr][nc]=2
    # Fill fully enclosed regions, keeping a central cell unfilled.
    remaining=set(enclosed)
    while remaining:
      p=remaining.pop();comp={p};stack=[p]
      while stack:
        r,c=stack.pop()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
