        comp=[];stack=[(r,c)];seen.add((r,c))
        while stack:
          x,y=stack.pop();comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and (nx,ny) not in seen:seen.add((nx,ny));stack.append((nx,ny))
        r0,r1=min(x for x,y in comp),max(x for x,y in comp);c0,c1=min(y for x,y in comp),max(y for x,y in comp)
        # The one-cell ring outside the rectangular extent.
        for y in range(c0-1,c1+2):
