            if 0<=x<h and 0<=y<w and grid[x][y]==0:out[x][y]=2
        for x in range(r0-1,r1+2):
          for y in (c0-1,c1+1):
            if 0<=x<h and 0<=y<w and grid[x][y]==0:out[x][y]=2
        # Fill enclosed zeros within bbox, retaining midpoint.
        zeros={(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1) if grid[x][y]==0}
        ext=set();q=collections.deque()
        for x,y in zeros:
          if x in (r0,r1) or y in (c0,c1):ext.add((x,y));q.append((x,y))
        while q:
          x,y=q.popleft()
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            t=(x+dx,y+dy)
            if t in zeros and t not in ext:ext.add(t);q.append(t)
        holes=zeros-ext
        if holes:
          # The unique untouched cell is the geometric bbox center (rounding up for even spans).
          center=((r0+r1+1)//2,(c0+c1+1)//2)
