              if 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and (nx,ny) not in seen:seen.add((nx,ny));q.append((nx,ny))
        r0,r1=min(x for x,y in comp),max(x for x,y in comp);c0,c1=min(y for x,y in comp),max(y for x,y in comp)
