    from collections import deque
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid];seen=set()
    # Apply changes by zero-valued 4-connected regions of the grid.
    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0};visited=set()
    for start in zeros:
      if start in visited:continue
      comp={start};q=[start];visited.add(start);touch=False
      while q:
        r,c=q.pop()
        if r in (0,h-1) or c in (0,w-1):touch=True
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
          p=(r+dr,c+dc)
          if p in zeros and p not in visited:visited.add(p);comp.add(p);q.append(p)
      if touch:continue
      # Interior void is color 3, except each object's central seed pixel remains 0.
      for r,c in comp:out[r][c]=3
    # Restore centers for cavities based on each enclosed 1-object bbox.
    one_seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in one_seen:continue
        obj=[];q=[(r,c)];one_seen.add((r,c))
        while q:
          x,y=q.pop();obj.append((x,y))
          for dx in (-1,0,1):
            for dy in (-1,0,1):
              t=x+dx,y+dy
              if 0<=t[0]<h and 0<=t[1]<w and grid[t[0]][t[1]]==1 and t not in one_seen:one_seen.add(t);q.append(t)
        r0,r1=min(x for x,y in obj),max(x for x,y in obj);c0,c1=min(y for x,y in obj),max(y for x,y in obj)
        pocket={(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1) if out[x][y]==3}
        if pocket:
          # Keep the geometric center uncolored where it belongs to the cavity.
          x,y=(r0+r1)//2,(c0+c1)//2
          if (x,y) in pocket:out[x][y]=0
          # Frame the exterior silhouette around every closed outline.
          for a,b in obj:
            for dx in (-1,0,1):
              for dy in (-1,0,1):
                na,nb=a+dx,b+dy
                if 0<=na<h and 0<=nb<w and grid[na][nb]==0 and out[na][nb]!=3:out[na][nb]=2
    return out
