 "content": "def transform(grid):
    from collections import deque
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]

    # Find zero regions that cannot reach the grid edge: these are the cavities.
    zero={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    exterior=set(); q=deque()
    for r,c in zero:
        if r==0 or r==h-1 or c==0 or c==w-1:
            exterior.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(r+dr,c+dc)
            if p in zero and p not in exterior:
                exterior.add(p);q.append(p)
    cavities=zero-exterior
    if not cavities:
        return out

    # Inner rim of each cavity is recolored 3; its deepest interior remains 0.
    for r,c in cavities:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
               for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
            out[r][c]=3

    # Find 8-connected 1 components bordering a cavity; give their outside rim color 2.
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen:
                continue
            comp=[];q=[(r,c)];seen.add((r,c)); borders=False
            while q:
                x,y=q.pop();comp.append((x,y))
                if any((x+dr,y+dc) in cavities for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
                    borders=True
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        p=(x+dr,y+dc)
                        if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
                            seen.add(p);q.append(p)
            if borders:
                for x,y in comp:
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            a,b=x+dr,y+dc
                            if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in cavities:
                                out[a][b]=2
    return out
