    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    visited=set();cavities=[]
    for start in zeros:
        if start in visited:continue
        comp={start};q=[start];visited.add(start);edge=False
        while q:
            r,c=q.pop()
            if r in (0,h-1) or c in (0,w-1):edge=True
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in zeros and p not in visited:visited.add(p);comp.add(p);q.append(p)
        if not edge:cavities.append(comp)
