          for dx in (-1,0,1):
            for dy in (-1,0,1):
              p=x+dx,y+dy
              if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:seen.add(p);q.append(p)
        r0,r1=min(x for x,y in comp),max(x for x,y in comp);c0,c1=min(y for x,y in comp),max(y for x,y in comp)
