            p=r+dr,c+dc
            if p in zeros and p not in exterior:exterior.add(p);q.append(p)
    cavities=zeros-exterior
    if not cavities:return out
    # Color cavity pixels in the inner 8-neighbor boundary layer; deeper cells remain 0.
    for r,c in cavities:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
               for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            out[r][c]=3
    # Add a one-cell 8-neighbor halo outside each cavity-enclosing contour.
    rim_ones=set()
    for r,c in cavities:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=r+dr,c+dc
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1:rim_ones.add(p)
    for r,c in rim_ones:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                a,b=r+dr,c+dc
                if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in cavities:
                    out[a][b]=2
    return out
