    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    # Enclosed zero regions are the interiors of the outlines.
    exterior=set();q=deque()
    for p in zeros:
        r,c=p
        if r in (0,h-1) or c in (0,w-1):exterior.add(p);q.append(p)
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=r+dr,c+dc
            if p in zeros and p not in exterior:exterior.add(p);q.append(p)
    cavities=zeros-exterior
    if not cavities:return out
    # Recolor just the 8-neighbor inner rim, leaving the deeper zero core unchanged.
    for r,c in cavities:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
               for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            out[r][c]=3
    # Halo the entire 8-connected outline(s) bordering cavities.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen:continue
