    from collections import deque
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    exterior=set();q=deque()
    for r,c in zeros:
        if r in (0,h-1) or c in (0,w-1):exterior.add((r,c));q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=r+dr,c+dc
            if p in zeros and p not in exterior:exterior.add(p);q.append(p)
    cavities=zeros-exterior
    if not cavities:return out
    # Color the cavity's inner rim (8-neighbor contact), retaining its deeper core.
    for r,c in cavities:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
               for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            out[r][c]=3
    # Expand the enclosing 1-contour one cell outward in all directions.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen:continue
        comp=[];q=[(r,c)];seen.add((r,c))
        while q:
          x,y=q.pop();comp.append((x,y))
          for dr in (-1,0,1):
            for dc in (-1,0,1):
              p=x+dr,y+dc
              if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
                seen.add(p);q.append(p)
        if not any((x+dr,y+dc) in cavities for x,y in comp
                   for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            continue
        for x,y in comp:
          for dr in (-1,0,1):
            for dc in (-1,0,1):
              a,b=x+dr,y+dc
              if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in cavities:
                out[a][b]=2
    return out
